      this.clock = new Clock();
      this.time = 0;
      this.updaters = [];
      this.focus = new Vector3(40, 0, 12);
      this.focusTarget = new Vector3(40, 0, 12);
      this.cam = { yaw: 0, pitch: 46 * Math.PI / 180, dist: 22, yawT: 0, pitchT: 46 * Math.PI / 180, distT: 22, shake: 0, punch: 0 };
