      scene.environmentIntensity = 0.14;
      await progress2("Carving the table\u2026");
      this.tex = {};
      this.tex.wood = makeWood(s.texSize);
      await progress2("Quarrying flagstones\u2026");
      this.tex.floor = makeFlagstone(s.texSize, { seed: 3 });
      await progress2("Laying walls\u2026");
      this.tex.wall = makeWall(s.texSize);
      this.tex.felt = makeFelt(512);
      this.buildLights();
