      torch.castShadow = s.torchShadows;
      torch.shadow.mapSize.set(1024, 1024);
      torch.shadow.bias = -2e-3;
      torch.shadow.normalBias = 0.05;
      torch.shadow.radius = 3;
      torch.shadow.camera.near = 0.3;
      torch.shadow.camera.far = 30;
