        g.fillStyle = "#6e4524";
        g.fillRect(60 + i * 340, 80, 270, 260);
        g.fillStyle = "#8a5a32";
        g.fillStyle = "#d8b46a";
        g.fillRect(180 + i * 340, 300, 30, 12);
        g.fillStyle = "#8a5a32";
